-- ============================================
-- Block Ops — Pilot seed for content objects
-- Seeds Foundation deliverables + current agent knowledge
-- Run after content-objects-setup.sql
-- ============================================

begin;

-- 1. Seed canonical objects
on conflict (object_id) do update set
  title = excluded.title,
  slug = excluded.slug,
  object_type = excluded.object_type,
  package = excluded.package,
  owner = excluded.owner,
  updated_at = now();

-- 2. Seed representations
on conflict (source_path) do update set
  object_id = excluded.object_id,
  representation_type = excluded.representation_type,
  knowledge_layer = excluded.knowledge_layer,
  audience = excluded.audience,
  workspace_visibility = excluded.workspace_visibility,
  review_status = excluded.review_status,
  scope_type = excluded.scope_type,
  site_id = excluded.site_id,
  agent_facing = excluded.agent_facing,
  version = excluded.version,
  storage_path = excluded.storage_path,
  updated_at = now();

-- 3. Summary checks
-- Expected after seed: 46 human foundation representations + 9 agent representations = 55 representations
-- Expected canonical objects: 46 total foundation objects (9 of them have both human + agent representations)

commit;
